const response = await client.cities.listCities({country: 'AU', state: 'VIC', limit: 20});
for (const city of response.map.cities) {
    console.log(city.id, city.name, city.post_code, city.state.code, city.country.code);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);
